   B=sum(p.astype(np.uint8) for p in P)
   A=sum((~P[i] & P[(i+1)%8]).astype(np.uint8) for i in range(8))
   if phase==0: cond=(~(p2&p4&p6))&(~(p4&p6&p8))
   else: cond=(~(p2&p4&p8))&(~(p2&p6&p8))
