 all_paths.append([(p[1]+x0,p[0]+y0) for p in path])
# draw skeletons/selected path on target crop
out=Image.open('/app/target.png').convert('RGB');d=ImageDraw.Draw(out)
for path in all_paths:
 for x,y in path:d.ellipse((x-1,y-1,x+1,y+1),fill=(255,0,0))
